# runner/tests/test_training_watch.py StallTest.test_first_sight_of_an_old_log_does_not_fire lines 301-312
def test_first_sight_of_an_old_log_does_not_fire(self):
        alerts, _state = _run([
            _readings(T0, lines=[(T0 - 7200, "step 9 loss: 0.4")]),
        ])
        self.assertEqual(alerts, [])
        # Once the watcher has a pass of history with that
        # log, its silence is judged like any other.
        alerts, _state = _run([
            _readings(T0, lines=[(T0 - 7200, "step 9 loss: 0.4")]),
            _readings(T0 + 60),
        ])
        self.assertEqual(_signals(alerts), ["training_stalled"])

# runner/tests/test_windows_surface.py SurfaceMechanicsTest.test_windll_fake_answers_neutrally lines 73-84
def test_windll_fake_answers_neutrally(self):
        restore = surface.apply_surface()
        try:
            self.assertEqual(
                ctypes.windll.shell32.IsUserAnAdmin(), 0)
            kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
            self.assertEqual(kernel32.GlobalMemoryStatusEx(None), 0)
            fn = ctypes.windll.kernel32.CreateToolhelp32Snapshot
            fn.argtypes = [ctypes.c_ulong, ctypes.c_ulong]
            self.assertEqual(fn(0, 0), 0)
        finally:
            restore()

