# runner/tests/test_extension_sources.py ProvisionTest.test_a_tampered_archive_is_refused lines 957-968
def test_a_tampered_archive_is_refused(self):
        decl = upstream_decl()
        write_ext(self.ext, decl)
        lock = self._lock_for(decl, upstream_routes())
        with open(os.path.join(self.ext, X.LOCK_FILE), "w") as fh:
            json.dump(lock, fh)
        self.opener.routes[ASSET] = tgz({"README": b"swapped"})
        self.run_pass()
        up = self.state()["entries"]["up"]
        self.assertEqual(up["status"], "mismatch")
        self.assertFalse(os.path.exists(os.path.join(
            self.entry_dir("up"), "source")))

# runner/tests/test_windows_surface.py SurfaceMechanicsTest.test_double_apply_keeps_the_first_restore_in_charge lines 137-148
def test_double_apply_keeps_the_first_restore_in_charge(self):
        # Compare against the value captured BEFORE applying --
        # on a real Windows host (or under the sim harness, which
        # has a layer applied already) that value IS "nt", and a
        # correct restore returns to it, not away from it.
        before = os.name
        restore = surface.apply_surface()
        noop = surface.apply_surface()
        noop()
        self.assertEqual(os.name, "nt")  # still applied
        restore()
        self.assertEqual(os.name, before)

# runner/tests/test_build_config.py PipelineLiftsTest.test_every_action_is_sha_pinned_with_a_version_comment lines 368-379
def test_every_action_is_sha_pinned_with_a_version_comment(self):
        pin = re.compile(r"uses:\s*\S+@[0-9a-f]{40}\s+#\s*\S+")
        checked = 0
        for name in self.WORKFLOWS:
            for line in self._wf(name).splitlines():
                if "uses:" in line:
                    checked += 1
                    self.assertRegex(
                        line, pin,
                        "%s: action not SHA-pinned with a version "
                        "comment: %s" % (name, line.strip()))
        self.assertGreaterEqual(checked, 30)

