# runner/tests/test_linux_platform.py JournalFallbackTest.test_mutations_that_are_not_a_readable_journal lines 478-489
def test_mutations_that_are_not_a_readable_journal(self):
        for kwargs in (
            {"platform": "linux", "stdout": "", "rc": 1},
            {"platform": "linux", "stdout": None, "rc": 0},
            {"platform": "linux", "boom": True},
            {"platform": "linux", "stdout": "failed password\n", "journal": False},
            {"platform": "darwin", "stdout": "failed password\n"},
        ):
            out, calls = self._tail(**kwargs)
            self.assertIsNone(out)
            if kwargs["platform"] != "linux" or kwargs.get("journal") is False:
                self.assertEqual(calls, [])

# runner/tests/test_protocol_and_edges.py AdversarialTests.test_fetch_search_uses_broad_tag lines 933-944
def test_fetch_search_uses_broad_tag(self):
        # Decorated subjects ("[HOMING-PIGEON] TEST job <id>") do not
        # contain the exact "[HOMING-PIGEON] job" substring, so the
        # search must use the broad tag and let handle_mail filter.
        imap = FakeIMAP([])
        searches = []
        orig_search = imap.search
        imap.search = lambda *a: (searches.append(a), orig_search(*a))[1]
        fetch_job_mails(imap)
        joined = " ".join(" ".join(str(x) for x in a) for a in searches)
        self.assertIn("[HOMING-PIGEON]", joined)
        self.assertNotIn("[HOMING-PIGEON] job", joined)

