        parts = JF._split_cmd_windows(
            r'"C:\Program Files\py.exe" C:\x\fake.py {variant}')
        self.assertEqual(parts, [r"C:\Program Files\py.exe",
                                 r"C:\x\fake.py", "{variant}"])
