def test_dry_run_verifies_but_changes_nothing(self):
        import types
        jid = str(uuid.uuid4())
        p = base_job(jid, kind="exec", script="echo hi")
        opts = types.SimpleNamespace(dry_run=True, no_send=False)
        imap, smtp, seen = self.cycle([job_email(p)], opts=opts)
        self.assertEqual(len(smtp.sent), 0)   # nothing sent
        self.assertEqual(seen, {})            # nothing recorded
        self.assertEqual(imap.flagged, [])    # nothing marked seen
        # ...but the signature was verified (a bad sig would reject).
        # No work dir means nothing executed.
        self.assertFalse(os.path.isdir(os.path.join(self.tmp, "work", jid)))

# runner/tests/test_build_config.py PipelineLessonsTest.test_no_test_count_census_in_workflows lines 785-796
def test_no_test_count_census_in_workflows(self):
        # `grep -q 'Ran 6 tests'` and `assertEqual(count, 1)` both
        # broke on 2026-10-21 the moment someone added a test or a
        # build. A verdict step asks for N > 0, a bare OK and no skip
        # (runner/tools/skip_guard.py --require-ok --no-skips), never a number.
        for name in self.ALL:
            for line in _workflow_text(name).splitlines():
                if line.strip().startswith("#"):
                    continue
                self.assertNotRegex(line, r"Ran \d+ tests?",
                                    "%s hardcodes a test count: %s"
                                    % (name, line.strip()))

