def test_moved_digest_refiles_as_changed(self):
        _a, state = self.decide([_file()])
        alerts, _state = self.decide([_file(sha384=DIGEST_B)],
                                     state=state)
        self.assertEqual([a["signal"] for a in alerts],
                         ["artifact_changed"])
        # And back again is a change too, not an arrival.
        _a, state = self.decide([_file(sha384=DIGEST_B)], state=state)
        alerts, _state = self.decide([_file()], state=state)
        self.assertEqual([a["signal"] for a in alerts],
                         ["artifact_changed"])
        self.assertEqual(alerts[0]["detail"]["old_sha384"], DIGEST_B)
        self.assertEqual(alerts[0]["detail"]["new_sha384"], DIGEST_A)

# runner/tests/test_cert_sentinel.py DecideTest.test_warn_band_holds_quietly_then_critical_files lines 115-127
def test_warn_band_holds_quietly_then_critical_files(self):
        alerts, state = _run([_cert(30)])
        self.assertEqual([a["signal"] for a in alerts], ["cert_expiring"])
        # 8 days left is still the warn band: quiet while it holds.
        alerts, state = _run([_cert(8)], state=state)
        self.assertEqual(alerts, [])
        self.assertEqual(state["seen"]["/certs/site.pem"]["band"], "warn")
        # Crossing into critical files the high signal, once.
        alerts, state = _run([_cert(7)], state=state)
        self.assertEqual([(a["signal"], a["severity"]) for a in alerts],
                         [("cert_critical", "high")])
        alerts, state = _run([_cert(3)], state=state)
        self.assertEqual(alerts, [])

