def test_vanished_listener_leaves_state_and_refiles_on_return(self):
        state = _learned_state(BASE)
        new = {"proto": "tcp", "addr": "127.0.0.1", "port": 8080}
        alerts, state = PW.decide(_readings(BASE, new), _manifest(), state)
        self.assertEqual(len(alerts), 1)
        # It vanishes: no alert, and its key leaves the state.
        alerts, state = PW.decide(_readings(BASE), _manifest(), state)
        self.assertEqual(alerts, [])
        self.assertNotIn("tcp/127.0.0.1/8080", state["seen"])
        # It returns: a moved reading, so it files again.
        alerts, _state = PW.decide(_readings(BASE, new),
                                   _manifest(), state)
        self.assertEqual([a["signal"] for a in alerts], ["new_listener"])

# runner/tests/test_linux_resources.py ProcMutations.test_bad_proc_text_is_none lines 88-100
def test_bad_proc_text_is_none(self):
        for text in ("", "bogus\n", "cpu\n", "cpu a b c\n", "cpu 1 2\n"):
            with mock.patch("builtins.open", _open_proc(text, "/proc/stat")):
                self.assertIsNone(RS._read_proc_stat(), text)
        for text in ("", "MemTotal: no\n", "MemFree: 1 kB\n",
                     "MemTotal: 0 kB\nMemAvailable: 1 kB\n",
                     "MemTotal: 10 kB\nMemAvailable: -1 kB\n"):
            with mock.patch("builtins.open", _open_proc(text, "/proc/meminfo")):
                got = RS._mem_fraction()
            self.assertTrue(got is None or 0.0 <= got <= 1.0, (text, got))
        with mock.patch("builtins.open", side_effect=OSError("gone")):
            self.assertIsNone(RS._read_proc_stat())
            self.assertIsNone(RS._mem_fraction())

# runner/tests/test_oracle_opinion.py ScriptHintTests.test_bash_only_tells lines 136-148
def test_bash_only_tells(self):
        # Syntax no dash/ash can run: shape is "bash", which does
        # not fit the sh default, so repair leaves it alone.
        self.assertEqual(op.script_shape("a=(1 2 3)\necho ${a[0]}"), "bash")
        self.assertEqual(op.script_shape("#!/bin/bash\nx+=(y)"), "bash")
        self.assertEqual(op.script_shape("cat <<< \"$x\""), "bash")
        self.assertEqual(op.script_shape("declare -A m\nm[k]=v"), "bash")
        self.assertEqual(op.script_shape("readarray -t L < f"), "bash")
        self.assertEqual(op.script_shape("echo ${#arr[@]}"), "bash")
        self.assertEqual(op.script_shape("cat <(echo hi)"), "bash")
        self.assertEqual(op.script_shape('echo "${x:0:1}"'), "bash")
        self.assertFalse(op._shape_fits("bash", "posix-shell"))
        self.assertFalse(op._shape_fits("bash", "powershell"))

