        alerts3, state = BF.decide(stale_readings, self.manifest, state)
        self.assertEqual([a["signal"] for a in alerts3],
                         ["backup_stale"])
        alerts4, state = BF.decide(stale_readings, self.manifest, state)
        self.assertEqual(alerts4, [])

