        state = {"last_fired": {
            "kernel_distress:oom": self.NOW - 100}}
        self.assertEqual(
            self._decide({"cooldown_sec": float("inf")}, state),
            [])
        # 4000s after a firing is past the documented
        # default cooldown: files again.
