# runner/tests/test_oracle.py AttestationFixTest.test_confined_three_states lines 308-322
def test_confined_three_states(self):
        from runner.runner import build_attestations
        q = [{"op": "attest", "predicate": "confined_to_workspace"}]
        base = {"exit_code": 0, "patterns": {}, "text": ""}
        # Unconfigured -> ok False, reason "unconfigured".
        atts = build_attestations(q, {**base, "confined": None})
        self.assertFalse(atts[0]["ok"])
        self.assertEqual(atts[0]["reason"], "unconfigured")
        # Confined -> ok True.
        atts = build_attestations(q, {**base, "confined": True})
        self.assertTrue(atts[0]["ok"])
        # Violation -> ok False, reason is NOT "unconfigured".
        atts = build_attestations(q, {**base, "confined": False})
        self.assertFalse(atts[0]["ok"])
        self.assertNotEqual(atts[0]["reason"], "unconfigured")

# runner/tests/test_crash_watch.py DecideTest.test_changed_file_at_same_path_refiles lines 192-206
def test_changed_file_at_same_path_refiles(self):
        _a, state = self.decide([_file(size=4096, mtime=100.0)])
        # Same path, changed size and mtime, after the window:
        # a fresh dump overwrote the old one and files again.
        alerts, _state = self.decide(
            [_file(size=8192, mtime=200.0)], state=state,
            now=T0 + WINDOW + 1)
        self.assertEqual([a["signal"] for a in alerts], ["crash_dumped"])
        self.assertEqual(alerts[0]["detail"]["size"], 8192)
        # Changed inside the window: still a new event, so it
        # files as the repeat it is.
        alerts, _state = self.decide(
            [_file(size=8192, mtime=200.0)], state=state, now=T0 + 60)
        self.assertEqual([a["signal"] for a in alerts],
                         ["crash_repeated"])

