def test_departure_is_silent_and_return_refiles(self):
        # The "moved reading" for a bus sense: a device leaves
        # (silently) and comes back -- the return is news again.
        state = _learn(KEYBOARD)
        alerts, state = UA.decide(_readings(KEYBOARD, STICK),
                                  self.manifest, state)
        self.assertEqual(len(alerts), 1)
        alerts, state = UA.decide(_readings(KEYBOARD),
                                  self.manifest, state)
        self.assertEqual(alerts, [])  # departure: no signal at all
        self.assertNotIn("0781:5567", state["seen"])
        alerts, state = UA.decide(_readings(KEYBOARD, STICK),
                                  self.manifest, state)
        self.assertEqual([a["signal"] for a in alerts],
                         ["storage_arrived"])

# runner/tests/test_zeek_feed.py DecidePeersTest.test_seen_peer_memory_is_bounded lines 312-326
def test_seen_peer_memory_is_bounded(self):
        manifest = _manifest()
        manifest["tunables"]["seen_peers_cap"] = 3
        manifest["tunables"]["new_peer_threshold"] = 99
        events = [_conn(T0 + i * 10, _peer(i)) for i in range(6)]
        alerts, state = self.decide(_readings(events), manifest=manifest)
        self.assertEqual(alerts, [])
        self.assertEqual(state["seen_peers"], [_peer(3), _peer(4), _peer(5)])
        # The evicted oldest peer counts as first-seen again:
        # that is the honest price of the bounded memory.
        manifest["tunables"]["new_peer_threshold"] = 1
        alerts, _state = self.decide(
            _readings([_conn(T0 + 100, _peer(0))]), state=state, manifest=manifest
        )
        self.assertEqual([a["signal"] for a in alerts], ["zeek_new_external_peers"])

