        self.assertNotIn(_CANARY, raw)
        outer = verify_body(good[0][1], SECRET)
        inner = decrypt_body(outer, SECRET, good_id, "")
        opened = verify_body(inner, SECRET)
        self.assertIn(_CANARY, json.dumps(opened))

