# runner/tests/test_softflowd_feed.py DecodeV9Test.test_template_and_data_in_one_datagram lines 183-198
def test_template_and_data_in_one_datagram(self):
        # Build one datagram carrying both flowsets.
        template = _v9_template_datagram()
        header, template_flowset = template[:20], template[20:]
        record = _v9_record()
        data_flowset = struct.pack("!HH", 256, 4 + len(record)) + record
        packet = header + template_flowset + data_flowset
        flows, _templates = SF.decode_datagram(packet)
        self.assertEqual(len(flows), 1)
        flow = flows[0]
        self.assertEqual(flow["version"], 9)
        self.assertEqual(flow["dst"], "8.8.8.8")
        self.assertEqual(flow["bytes"], 5000)
        # sysUpTime anchor 200_000 ms: first 110_000, last 200_000.
        self.assertEqual(flow["first"], SECS - 90.0)
        self.assertEqual(flow["last"], float(SECS))

# runner/tests/test_oracle_intake_fuzz.py RingTwoBoardTest.test_cleartext_opens_nothing_and_the_envelope_does lines 1443-1458
def test_cleartext_opens_nothing_and_the_envelope_does(self):
        bad_id = "task-bad-1"
        wire = self._wire(bad_id)
        flipped = (
            wire[:-2] + ("0" if wire[-2] != "0" else "1") + wire[-1])
        self.assertEqual(self._send(bad_id, flipped), [])
        self.assertNotIn(bad_id, self.board.tasks)
        plain_id = "task-plain-1"
        self.assertEqual(self._send(plain_id, self._wire(plain_id)), [])
        self.assertNotIn(plain_id, self.board.tasks)
        good_id = "task-good-1"
        out = self._send(good_id, self._sealed(good_id))
        self.assertEqual(self.board.tasks[good_id]["state"], "open")
        raw = " ".join(body for _s, body, _t in out)
        self.assertNotIn("file me", raw)
        self.assertIn("task_ack", " ".join(s for s, _b, _t in out))

