def test_one_worker_crash_does_not_drop_the_others(self):
        with tempfile.TemporaryDirectory() as d:
            seen = {}

            def boom(cfg, imap, smtp, seq, raw, base_dir, seen_map,
                     secrets, opts=None, key_policies=None):
                if str(seq) == "1":
                    raise RuntimeError("extension blew up")
                return handle_mail(cfg, imap, smtp, seq, raw, base_dir,
                                   seen_map, secrets, opts, key_policies)

            with mock.patch("runner.runner.handle_mail", side_effect=boom):
                poll_once(_cfg(), d, seen, os.path.join(d, "seen.json"),
                          imap=_IMAP(_pings()), smtp=_SMTP(), opts=_Opts())
            self.assertNotIn("ping-0", seen)
            self.assertEqual(len(seen), 5)

# runner/tests/test_extension_sources.py ProvisionTest.test_bytes_that_differ_from_the_pin_are_refused lines 940-955
def test_bytes_that_differ_from_the_pin_are_refused(self):
        decl = upstream_decl()
        write_ext(self.ext, decl)
        with open(os.path.join(self.ext, X.LOCK_FILE), "w") as fh:
            json.dump(self._lock_for(decl, upstream_routes(), tamper=True),
                      fh)
        self.run_pass()
        up = self.state()["entries"]["up"]
        self.assertEqual(up["status"], "mismatch")
        self.assertIn("digest mismatch", up["detail"])
        self.assertEqual(up["next_retry_at"], self.now + X.RETRY_CAP_SEC)
        self.assertFalse(os.path.exists(os.path.join(
            self.entry_dir("up"), "files", "LICENSE")))
        self.assertFalse(os.path.exists(os.path.join(
            self.entry_dir("up"), "source")))
        self.assertNotIn("upstream up", X.oracle_note(self.base))

# runner/tests/test_protocol_and_edges.py InfiniteRetryBugs.test_empty_list_interpreter_rejected_not_retried lines 635-650
def test_empty_list_interpreter_rejected_not_retried(self):
        # A present-but-empty interpreter is malformed, not
        # absent: it must be refused, never silently replaced
        # by the platform default (which is what an `or` chain
        # over the job value did -- the job then ran, and on a
        # platform whose default shell exits 0 on the script,
        # recorded success).
        jid = str(uuid.uuid4())
        p = base_job(jid, kind="exec", script="echo hi", interpreter=[])
        imap, smtp, seen = self.cycle([job_email(p)])
        self.assertEqual(len(smtp.sent), 1)
        r = read_result(smtp.sent[0])
        self.assertEqual(r["exit_code"], -2)
        self.assertIn("interpreter must be", r["stderr"])
        self.assertIn("1", imap.flagged)
        self.assertIn(jid, seen)

