def test_boot_json_cannot_break_out(self):
        nasty = [
            ('tok</script><script>alert(1)', "m", True),
            ('a"b', "m", True),
            ("tok", "model\nwith\nlines", True),
            ("tok", "model\\with\\slashes", False),
            ("", "", False),
        ]
        for token, model, ready in nasty:
            page = oracle_page(token, model, ready)
            js = _script(page)
            self.assertEqual(page.count("<script>"), 1, token)
            self.assertNotIn("</script>", js, token)
            # The boot object is JSON, so it round-trips.
            blob = js[js.find("const boot = ") + len("const boot = "):]
            blob = blob[:blob.find(";")]
            got = json.loads(blob)
            self.assertEqual(got["ready"], ready)

# runner/tests/test_windows_surface.py SurfaceMechanicsTest.test_apply_and_restore_is_total lines 47-64
def test_apply_and_restore_is_total(self):
        before = (os.name, sys.platform, hasattr(os, "sysconf"),
                  hasattr(ctypes, "windll"))
        restore = surface.apply_surface()
        try:
            self.assertEqual(os.name, "nt")
            self.assertEqual(sys.platform, "win32")
            self.assertFalse(hasattr(os, "sysconf"))
            self.assertFalse(hasattr(os, "getloadavg"))
            self.assertFalse(hasattr(os, "fork"))
            import platform
            self.assertEqual(platform.system(), "Windows")
            self.assertEqual(platform.machine(), "AMD64")
        finally:
            restore()
        after = (os.name, sys.platform, hasattr(os, "sysconf"),
                 hasattr(ctypes, "windll"))
        self.assertEqual(before, after)

