            changed = R.reload_hot_config(cfg, path, state)
            self.assertIn("oracle_mode", changed)
            self.assertEqual(cfg["oracle_mode"], "deterministic")
            self.assertIsNone(R.inference_config(
                dict(cfg, inference=dict(INF))))

