# runner/tests/test_job_fuzz.py ReadLiveTest.test_campaign_runs_and_archives_variants lines 370-388
def test_campaign_runs_and_archives_variants(self):
        self._retain(_seed(saved_at=time.time() - 3600))
        m = self._manifest_with(
            runner_cmd=f"{sys.executable} {self.fake} {{variant}}")
        # Seed 4 rotates the mutator order onto
        # interpreter_string, whose variant must be refused.
        readings = JF.read_live(m, {"campaign_seed": 4})
        self.assertTrue(readings["idle"])
        self.assertTrue(readings["outcomes"])
        for outcome in readings["outcomes"]:
            self.assertEqual(outcome["job_id"], "job-a")
            self.assertIn(outcome["stage"],
                          ("ran", "refused", "error"))
            archived = os.path.join(
                self.tmp, "work", outcome["variant_file"])
            self.assertTrue(os.path.isfile(archived))
        refusals = [o for o in readings["outcomes"]
                    if o["stage"] == "refused"]
        self.assertTrue(refusals)  # interpreter_string bit

# runner/tests/test_oracle_intake_fuzz.py RingTwoBoardTest.test_a_claimed_task_can_be_finished_once lines 1508-1526
def test_a_claimed_task_can_be_finished_once(self):
        task_id = "task-claim-1"
        self._send(task_id, self._sealed(task_id))
        request = self._kind(
            "task_request", "w1", capabilities=["py"])
        self._send_kind("task_request", "w1", request)
        self.assertEqual(self.board.tasks[task_id]["state"], "claimed")
        self._send_kind(
            "task_result", task_id,
            self._kind("task_result", task_id, result={"ok": True}))
        self.assertEqual(self.board.tasks[task_id]["state"], "done")
        self.assertEqual(self.board.tasks[task_id]["result"], {"ok": True})
        self._send_kind(
            "task_result", task_id,
            self._kind("task_result", task_id, result={"ok": False}))
        self.assertEqual(self.board.tasks[task_id]["result"], {"ok": True})
        other = "task-claim-2"
        self._send(other, self._sealed(other))
        self.assertEqual(self.board.tasks[other]["state"], "open")

