# runner/tests/test_install_edges.py FetchAndConfigTest.test_the_os_release_version_is_the_quoted_id lines 195-214
def test_the_os_release_version_is_the_quoted_id(self):
        text = 'NAME="Debian"\nVERSION_ID="12"\n'

        class _F:
            def __enter__(self):
                return self

            def __exit__(self, *a):
                return False

            def __iter__(self):
                return iter(text.splitlines(True))

        def opener(path, *a, **k):
            if path == "/etc/os-release":
                return _F()
            raise OSError(path)

        with mock.patch("builtins.open", opener):
            self.assertEqual(inst._os_release_version(), "12")

