# runner/tests/test_windows_surface.py WindowsDispatchPinsTest.test_sysconf_fallback_swallows_attribute_error lines 172-191
def test_sysconf_fallback_swallows_attribute_error(self):
        # The exact 3.8.9 shape: a platform that is neither the
        # Linux /proc route nor nt reaches the sysconf fallback;
        # where sysconf does not exist the AttributeError is the
        # documented "no route" answer, not a crash.
        from runner.oracle import remediation
        # sysconf may already be absent (the sim harness deletes
        # it for the whole process); the pin then starts from the
        # environment it is actually testing and restores only
        # what it took.
        saved = getattr(os, "sysconf", None)
        if saved is not None:
            del os.sysconf
        try:
            with mock.patch.object(sys, "platform", "darwin"), \
                    mock.patch.object(os, "name", "posix"):
                self.assertIsNone(remediation.total_memory_bytes())
        finally:
            if saved is not None:
                os.sysconf = saved

# runner/tests/test_cli_options.py WakeGateVerboseTest.test_fire_cooldown_and_inflight_each_narrate lines 420-439
def test_fire_cooldown_and_inflight_each_narrate(self):
        runner._set_verbosity(2)
        rec = {"sensor": "smoke", "signal": "alarm",
               "severity": "high"}
        with _captured_log() as buf:
            ok = runner._wake_gate_decide({}, rec, now=1000.0)
        self.assertTrue(ok)
        self.assertIn("score=3 >= high 3", buf.getvalue())
        self.assertIn("waking the Oracle", buf.getvalue())
        # Still in flight: the next alert is narrated as such.
        with _captured_log() as buf:
            ok = runner._wake_gate_decide({}, rec, now=1010.0)
        self.assertFalse(ok)
        self.assertIn("already in flight", buf.getvalue())
        # Flight released, cooldown still running: narrated too.
        runner._wake_gate_release()
        with _captured_log() as buf:
            ok = runner._wake_gate_decide({}, rec, now=1010.0)
        self.assertFalse(ok)
        self.assertIn("cooldown is 900s", buf.getvalue())

