def test_a_redacted_view_does_not_return_the_canary(self):
        path = self._retained()
        with open(path, encoding="utf-8") as f:
            data = json.load(f)
        data["view"] = "redacted"
        data["patterns"] = {"canary": _CANARY}
        with open(path, "w", encoding="utf-8") as f:
            json.dump(data, f)
        qid = uuid.uuid4().hex
        out = self._ask(qid, self._sealed(qid))
