# runner/tests/test_falco_feed.py MainTest.test_failed_local_delivery_leaves_the_state_unwritten lines 334-354
def test_failed_local_delivery_leaves_the_state_unwritten(self):
        # No signing secret in the environment: delivery cannot
        # be set up, main returns 2, and the state file is never
        # written -- so the reader offsets cannot have advanced
        # and the next pass re-reads the same lines.
        with tempfile.TemporaryDirectory() as d:
            state_path = os.path.join(d, "state.json")
            env = dict(os.environ)
            env.pop("HOMING_PIGEON_SENSOR_SECRET", None)
            old = os.environ.copy()
            os.environ.clear()
            os.environ.update(env)
            try:
                rc = FF.main(["--log-file", FIXTURE,
                              "--state", state_path,
                              "--local-dir", d])
            finally:
                os.environ.clear()
                os.environ.update(old)
            self.assertEqual(rc, 2)
            self.assertFalse(os.path.exists(state_path))

# runner/tests/test_linux_process.py KillMutations.test_pid_and_platform_mutations lines 62-82
def test_pid_and_platform_mutations(self):
        for pid in (0, -1, None, "42", 1):
            proc = _proc(pid)
            with mock.patch("runner.runner.os.name", "posix"), \
                 mock.patch("runner.runner.os.killpg") as killpg, \
                 mock.patch("runner.runner.subprocess.run",
                            side_effect=AssertionError("taskkill")):
                kill_tree(proc)
            self.assertEqual(killpg.call_args.args[1], signal.SIGKILL)
            self.assertIs(killpg.call_args.args[0], pid)

        proc = _proc(42)
        with mock.patch("runner.runner.os.name", "nt"), \
             mock.patch("runner.runner.os.killpg",
                        side_effect=AssertionError("killpg")), \
             mock.patch("runner.runner.subprocess.run") as run:
            kill_tree(proc)
        argv = run.call_args.args[0]
        self.assertEqual(argv[:3], ["taskkill", "/PID", "42"])
        self.assertIn("/T", argv)
        self.assertIn("/F", argv)

