            with open(path, "ab") as fh:
                fh.write(b"\nchanged\n")
            edited = _canary_watch(d)
            self.assertIn("modified", edited)
            self.assertIn(name, edited)
            quiet = _canary_watch(d)
            self.assertIn("modified", quiet)
            os.remove(path)
